            const model = historyRef.current.present;
            const trace = runSimulation(model);
            if (trace.steps.length === 0) {
              setLastError("No executable processes found");
              return prev;
            }
            setLastError(null);
            return {
              ...prev,
              mode: "select" as EditorMode,
              simulation: {
                trace,
                currentStepIndex: -1,
                status: "paused",
                speed: 800,
                frozenModel: model,
              },
