          }
          case "step": {
            if (!sim) return prev;
            const dir = (effect.payload ?? 1) as number;
            const maxIdx = sim.trace.steps.length - 1;
            const newIdx = Math.max(-1, Math.min(maxIdx, sim.currentStepIndex + dir));
            const atEnd = newIdx >= maxIdx;
            return {
              ...prev,
              simulation: {
                ...sim,
                currentStepIndex: newIdx,
                status: atEnd
