                  : sim.status === "running" ? "running" : "paused",
              },
            };
          }
          case "reset":
            setLastError(null);
            return { ...prev, simulation: null };
          case "setStep": {
            if (!sim) return prev;
            const idx = effect.payload as number;
            const maxIdx = sim.trace.steps.length - 1;
            const clamped = Math.max(-1, Math.min(maxIdx, idx));
            return {
