    }
    case "input":
    case "output":
      markerEnd = "url(#arrow-proc)";
      break;
    // Structural links: ISO §6 — distinct markers per type
    case "aggregation":
      markerEnd = "url(#triangle-filled)";    // ▲ filled triangle
