          x={mid.x} y={mid.y + (link.rate ? 14 : 5)}
          textAnchor="middle">
          {Math.round(link.probability * 100)}%
        </text>
      )}
      {link.multiplicity_source && (
        <text fontSize={9} fill="#666" fontWeight="bold"
          x={p1.x + (p2.x - p1.x) * 0.12} y={p1.y + (p2.y - p1.y) * 0.12 - 6}
          textAnchor="middle">
          {link.multiplicity_source}
        </text>
      )}
      {link.multiplicity_target && (
        <text fontSize={9} fill="#666" fontWeight="bold"
          x={p1.x + (p2.x - p1.x) * 0.88} y={p1.y + (p2.y - p1.y) * 0.88 - 6}
          textAnchor="middle">
          {link.multiplicity_target}
        </text>
      )}
      {link.path_label && (
        <g transform={`translate(${mid.x}, ${mid.y - 18})`}>
          <rect x={-4} y={-8} width={link.path_label.length * 5.5 + 8} height={14} rx={3}
            fill="rgba(0,0,0,0.5)" stroke="rgba(88,166,255,0.4)" strokeWidth={0.5} />
          <text fontSize={8} fill="rgba(88,166,255,0.9)" x={0} y={3} textAnchor="start">
            {link.path_label}
          </text>
