      const count = sf.visible.length + (sf.hiddenCount > 0 ? 1 : 0);
      extraH += count * 14 + 8;
    }
    return {
      x: app.x + ox,
      y: app.y + oy,
      w: app.w,
      h: app.h + extraH,
