            if (thing?.kind === "process") {
              subs.push({ id, name: thing.name, x: app.x, y: app.y, w: app.w, h: app.h });
            }
          }
          subs.sort((a, b) => a.y - b.y || a.x - b.x);
          if (subs.length < 2) return null;

