                    <line x1={midX} y1={fromY + 4} x2={midX} y2={toY - 4}
                      stroke="var(--accent)" strokeWidth={1} strokeDasharray="4,3" opacity={0.5} />
                    <polygon points={`${midX - 3},${toY - 8} ${midX + 3},${toY - 8} ${midX},${toY - 3}`}
                      fill="var(--accent)" opacity={0.5} />
                  </g>
                );
              })}
            </g>
          );
        })()}

