          const { thing, appearance: app } = entry;
          const allStates = statesForThing(model, thingId);
          const states = visibleStatesFor(allStates, thingId);
          return (
            <g key={`implicit-${thingId}`} style={{ opacity: 0.4 }}>
              <ThingNode
                thing={thing}
                appearance={app}
                states={states}
                isSelected={false}
                isDragging={false}
                isLinkSource={false}
